schema.sql:
CREATE ROLE app NOLOGIN;
CREATE ROLE invoice_audit_purger NOLOGIN;

CREATE TABLE accounts (id text PRIMARY KEY,is_demo boolean NOT NULL);
CREATE TABLE orders (id text PRIMARY KEY,account_id text NOT NULL REFERENCES accounts(id),state text NOT NULL DEFAULT 'NEW');
CREATE TABLE invoice_audit (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id) ON DELETE RESTRICT);

CREATE FUNCTION reject_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' AND current_user = 'invoice_audit_purger' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'invoice audit is immutable';
END $$;
CREATE TRIGGER invoice_audit_immutable BEFORE UPDATE OR DELETE ON invoice_audit FOR EACH ROW EXECUTE FUNCTION reject_audit_mutation();
CREATE TRIGGER invoice_audit_no_truncate BEFORE TRUNCATE ON invoice_audit FOR EACH STATEMENT EXECUTE FUNCTION reject_audit_mutation();

CREATE FUNCTION complete_order(order_id text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN INSERT INTO invoice_audit(order_id) VALUES (complete_order.order_id); UPDATE orders SET state='DONE' WHERE id=complete_order.order_id; END $$;

GRANT USAGE ON SCHEMA public TO invoice_audit_purger;
GRANT SELECT, DELETE ON accounts, orders, invoice_audit TO invoice_audit_purger;
CREATE FUNCTION purge_demo_account(account_id text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $$
DECLARE
  unhandled text;
BEGIN
  -- These are the restrictive references handled by the deletes below. Check
  -- before changing data so new child tables cannot be silently overlooked.
  SELECT string_agg(format('%s -> %s', c.conrelid::regclass, c.confrelid::regclass), ', ' ORDER BY c.conrelid::regclass::text)
    INTO unhandled
    FROM pg_constraint AS c
   WHERE c.contype = 'f' AND c.confdeltype IN ('a', 'r')
     AND c.confrelid IN ('public.accounts'::regclass, 'public.orders'::regclass, 'public.invoice_audit'::regclass)
     AND NOT EXISTS (
       SELECT 1 FROM (VALUES
         ('public.orders'::regclass, 'public.accounts'::regclass),
         ('public.invoice_audit'::regclass, 'public.orders'::regclass)
       ) AS handled(child, parent)
       WHERE handled.child = c.conrelid AND handled.parent = c.confrelid
     );
  IF unhandled IS NOT NULL THEN
    RAISE EXCEPTION 'unhandled restrictive foreign key references: %', unhandled USING ERRCODE = 'P0001';
  END IF;

  DELETE FROM public.invoice_audit AS audit
   USING public.orders AS o, public.accounts AS a
   WHERE audit.order_id = o.id AND o.account_id = a.id
     AND a.id = purge_demo_account.account_id AND a.is_demo;
  DELETE FROM public.orders AS o USING public.accounts AS a
   WHERE o.account_id = a.id AND a.id = purge_demo_account.account_id AND a.is_demo;
  DELETE FROM public.accounts AS a WHERE a.id = purge_demo_account.account_id AND a.is_demo;
END $$;
ALTER FUNCTION purge_demo_account(text) OWNER TO invoice_audit_purger;
REVOKE ALL ON FUNCTION purge_demo_account(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION purge_demo_account(text) TO app;

GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO app;

